export function apportion(total,weights){const sum=weights.reduce((a,b)=>a+b,0);if(!sum)return weights.map(()=>0);const exact=weights.map(w=>total*w/sum),result=exact.map(Math.floor);let left=total-result.reduce((a,b)=>a+b,0);const order=exact.map((n,i)=>({i,r:n-result[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let k=0;k<left;k++)result[order[k%order.length].i]++;return result}
export function calculate(people,items,tax,service,discount){const subtotal=items.reduce((s,i)=>s+i.price,0),net=subtotal+tax+service-discount;const weights=people.map(()=>0);let unassigned=0;for(const item of items){const owners=people.map((p,i)=>item.owners.includes(p.id)?i:-1).filter(i=>i>=0);if(!owners.length)unassigned++;else for(const i of owners)weights[i]+=item.price/owners.length}const valid=items.length>0&&people.length>0&&subtotal>0&&net>=0&&!unassigned&&items.every(i=>i.name.trim()&&Number.isSafeInteger(i.price)&&i.price>=0);return {subtotal,net,unassigned,valid,weights,shares:valid?apportion(net,weights):people.map(()=>0)}}
